                        float r2 = glm::dot(diff, diff);

                        if (r2 < h2 && r2 > 0.0f) {
                            float r = sqrt(r2);
                            float pressure_i = pi.pressure;
                            float pressure_j = pj.pressure;
                            float density_i = pi.density;
